import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const group = new Group();

  // Geometry and material for the textured plane
  const geometry = new PlaneGeometry(1, 1);
  const material = new MeshBasicNodeMaterial({ color: 0xffffff, map: null });
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load texture asynchronously; function remains synchronous
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
  });

  // Store references for cleanup
  const primitiveInstances = [];

  // Apply any cinematic primitives defined in the config
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const instance = ctx.primitives[prim.name](group, prim.params);
      primitiveInstances.push(instance);
    }
  }

  // User data for event handlers and cleanup
  group.userData = {
    handlers: {},
    cleanup() {
      // Dispose primitives
      for (const p of primitiveInstances) {
        if (p && typeof p.cleanup === 'function') p.cleanup();
      }
      // Dispose geometry and material
      geometry.dispose();
      material.dispose();
      // Dispose texture if it was loaded
      if (material.map) material.map.dispose();
      // Kill any GSAP timelines (none in this node)
      gsap.globalTimeline.clear();
    },
  };

  return group;
}
